input.command:
last=""
while true; do
  j=$(curl -s "https://api.github.com/repos/missingbulb/Sheepdog/actions/workflows/fleet-baseline.yml/runs?per_page=1")
  s=$(echo "$j" | python3 -c "import sys,json
try:
  r=json.load(sys.stdin)['workflow_runs'][0]; print(f\"{r['id']} {r['status']} {r['conclusion']}\")
except Exception: print('poll-error')")
  case "$s" in
    *completed*) echo "fleet re-force finished: $s"; exit 0;;
    poll-error) ;;
    *) if [ "$s" != "$last" ]; then last="$s"; fi;;
  esac
  sleep 90
done

