557	
558	  git(['-C', root, 'checkout', '-B', branch]);
559	  git(['-C', root, 'add', '-A']);
560	  // Withhold what this token cannot push (see withheldWorkflowPaths). Unstaged, not
561	  // reverted: the file stays in the working tree so nothing here has to reason about
562	  // restoring it, and the runner is discarded at job end either way. The agent lands
563	  // them on this same branch afterwards.
564	  for (const p of withheld) git(['-C', root, 'restore', '--staged', p]);
565	  // With everything else staged, a converge whose ONLY content was a workflow file has
566	  // nothing left to commit. It still needs the branch and the PR — that is where the
567	  // agent does its half — so the commit is allowed to be empty rather than skipped.
568	  const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
569	  const note = withheld.length
570	    ? `\n\nWithheld for the agent stage (the Action token cannot push a workflow file):\n${withheld.map((p) => `- ${p}`).join('\n')}`
571	    : '';
572	  git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
573	    'commit', ...(staged.length ? [] : ['--allow-empty']),
574	    '-m', `Claudinite maintenance: converge vendored mount, wiring, and migration notes${note}`]);
575	  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
576	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
577	
578	  const body = delivery === 'auto-merge'
579	    ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; auto-merges once this repo\'s checks pass.'
580	    : 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; left for your review.';
581	  const created = await gh(token, `/repos/${repo}/pulls`, {
582	    method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
583	  });
584	  const failure = pullCreateError(created.status, created.json);
585	  if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
586	  pr = created.json;
587	
588	  // ARM GitHub's native auto-merge (not an immediate merge): the PR lands
589	  // automatically once this repo's required checks pass, and the run never blocks
590	  // on CI. Auto-merge is a GraphQL-only mutation.
591	  //
592	  // Every cycle opens its own PR and arms it, so the arm is never stale — and it
593	  // is no longer the only thing standing between a converge and `main`: the arm
594	  // failing (auto-merge off, or a gated pull_request run) now costs one cycle,
595	  // not forever, because the next cycle merges this PR on its concluded runs
596	  // (pullDisposition) or closes it and re-cuts. Idempotent either way.
597	  // Start the PR's checks FIRST — the GITHUB_TOKEN push/open above emitted no
598	  // pull_request event, so without this the PR has no runs (#565, the
599	  // ciDispatchPlan block). AFTER the push, so the dispatched runs execute the
600	  // branch's own head; every delivering cycle, since a force-push emits no
601	  // synchronize event either and each new head needs its own runs. Best-effort:
602	  // a dispatch failure must not fail the converge that was already pushed.
603	  //
604	  // It runs BEFORE the delivery decision because it is what establishes whether
605	  // this repo has any PR CI at all — the fact deliveryAction turns on.
606	  const ci = await dispatchCiRuns(token, repo, branch)
607	    .catch((e) => { console.log(`baselining: CI dispatch on ${branch} failed: ${e.message}`); return null; });
608	  const hasPrCi = ci ? ci.dispatch.length + ci.missing.length > 0 : true; // unknown → assume CI, never merge blind
609	
610	  if (pr?.number) {
611	    const action = deliveryAction({ delivery, hasPrCi });
612	    if (action === 'merge') {
613	      const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
614	        method: 'PUT', body: { merge_method: 'squash' },
615	      });
616	      if (res.status === 200) { merged = true; console.log(`baselining: merged PR #${pr.number} directly — this repo has no pull_request CI to gate on`); }
617	      else console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`);
618	    } else if (action === 'arm' && pr.node_id) {
619	      // Surfaced, not swallowed: a failed arm is why a maintenance PR sits open
620	      // forever, and the two usual causes are both fixable repo settings.
621	      const armed = await enableAutoMerge(token, pr.node_id).then(() => true)
622	        .catch((e) => {
623	          console.log(`baselining: could not arm auto-merge on PR #${pr.number}: ${e.message}`
624	            + ' — check Settings → General → "Allow auto-merge", and Settings → Actions → General for a'
625	            + ' workflow-approval requirement parking this PR\'s pull_request run at action_required.'
626	            + ' Waiting for this cycle\'s dispatched run and landing it here.');
627	          return false;
628	        });
629	      // Only where the arm failed. A member that armed is GitHub's to land, and
630	      // waiting on it here would add a poll to every healthy repo for nothing.
631	      if (!armed && await landNow(token, repo, pr, delivery)) merged = true;
632	    }
633	  }
634	  // What this cycle delivered. The scheduler records it in the dispatch issue, which is
635	  // the agent's source for these artifacts.
636	  return { branch, pr: pr?.number ?? null, merged };
637	}
638	
639	// The I/O half of same-cycle landing: poll this PR's head sha until its runs have
640	// concluded, then merge on the same evidence disposal would use a day later.
641	// Returns true iff it merged. Best-effort throughout — every failure path leaves
642	// the PR exactly as the arm left it, which is what the next cycle expects.
643	const sleep = (ms) => new Promise((resolve) => { setTimeout(resolve, ms); });
644	
645	async function landNow(token, repo, pr, delivery) {
646	  const started = Date.now();
647	  for (;;) {
648	    const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha ?? ''}&per_page=100`);
649	    if (status !== 200) {
650	      console.log(`baselining: could not read this cycle's runs for PR #${pr.number} (HTTP ${status}) — leaving it for the next cycle`);
651	      return false;
652	    }
653	    const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
654	    const attempt = landAttempt({ delivery, runs, elapsedMs: Date.now() - started });
655	
656	    if (attempt === 'poll') { await sleep(LAND_POLL_MS); continue; }
657	    if (attempt === 'give-up') {
658	      console.log(`baselining: PR #${pr.number} not landable this cycle (${failureSummary(runs)})`
659	        + ' — leaving it open for the next cycle to dispose of');
660	      return false;
661	    }
662	
663	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
664	      method: 'PUT', body: { merge_method: 'squash' },
665	    });
666	    if (res.status === 200) {
667	      console.log(`baselining: merged PR #${pr.number} in-cycle — ${mergeReason(runs)}`);
668	      await deleteBranch(token, repo, pr.head?.ref);
669	      return true;
670	    }
671	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
672	      + ' — leaving it for the next cycle');
673	    return false;
674	  }
675	}
676	
677	// The I/O half of the disposal: read the workflow runs for the open PR's head
678	// sha, decide with pullDisposition, and either merge it (last cycle's content is
679	// verified — the arm just never landed it) or close it and delete its branch so
680	// this cycle re-cuts from scratch. Returns the PR when it still stands (a `wait`,
681	// a `review` member, or a failed attempt), null when the way is clear.
682	//
683	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it
684	// found it, and the cycle skips rather than piling a second PR on top.

